import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { addShippingMethodToCartWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await addShippingMethodToCartWorkflow(req.scope)
    .run({
      input: {
        cart_id: "cart_123",
        options: [{
            id: "so_123",
          },
          {
            id: "so_124",
            data: {
              carrier_code: "fedex",
            }
          }
        ]
      }
    })

  res.send(result)
}

